#!/bin/sh
# Builds Smaragd Dash: graphics, caves and music are generated by the Python tools
# in tools/, then everything is compiled into build/smaragd-dash.prg, which
# goes onto the disk image build/smaragd-dash.d81 together with the title
# logo (build/gen/logo.bin). The game loads the logo from that disk.
# Called by .vscode/run-current.sh with the compiler in $MEGA65_CC.

set -e
cd "$(dirname "$0")"
CC=${MEGA65_CC:-../toolchain/llvm-mos/bin/mos-mega65-clang}

mkdir -p build/gen
python3 tools/mkgfx.py build/gen build/preview.png
python3 tools/mkcave.py build/gen caves/*.cave
python3 tools/mkmusic.py build/gen
# shellcheck disable=SC2086
"$CC" -Os -g -Wall $SMARAGD_CFLAGS -Isrc -Ibuild/gen -o build/smaragd-dash.prg \
    -Wl,-Map=build/smaragd-dash.map src/*.c src/*.s build/gen/*.c
../toolchain/tools/bin/mkd81.py build/smaragd-dash.d81 "SMARAGD DASH" \
    "build/smaragd-dash.prg=SMARAGD DASH" "build/gen/logo.bin=SMARAGD.LOGO"
